<script setup lang="ts">
import { ref, watch, onMounted, computed } from 'vue'
import AppIcon from '../components/AppIcon.vue'
import ExtensionsManager from '../components/ExtensionsManager.vue'
import ModelManager from '../components/ModelManager.vue'
import {useRoute,useRouter} from 'vue-router'
import { state, ui, notify, saveSettings, request } from '../store'
const route=useRoute(),router=useRouter(),saving=ref(false),accountBusy=ref(false),accountError=ref(''),showPassword=ref(false),confirmPassword=ref(''),connection=ref('http'),client=ref('codex')
const tab = ref('model')
watch(()=>route.query.tab,value=>{if(value==='account'&&ui.deploymentMode==='local'){tab.value='model';return}if(['model','skills','mcp','external','account'].includes(String(value)))tab.value=String(value)},{immediate:true})
const accounts=ref<{id:string;username:string;role:string}[]>([]),newAccount=ref({username:'',password:''})
async function loadAccounts(){if(ui.deploymentMode==='server'&&ui.user?.role==='admin')accounts.value=await request('/admin/accounts')}
async function addAccount(){accountBusy.value=true;try{await request('/admin/accounts',newAccount.value);newAccount.value={username:'',password:''};await loadAccounts();notify('账号已创建')}catch(e){notify(String(e))}finally{accountBusy.value=false}}
const tokens=ref<{id:string;name:string;createdAt:string}[]>([]),tokenName=ref('Codex'),newToken=ref('')
const passwords=ref({current_password:'',new_password:''})
async function loadTokens(){tokens.value=await request('/auth/tokens')}
onMounted(()=>{void loadTokens();void loadAccounts()})
async function createToken(){try{const token=await request('/auth/tokens',{name:tokenName.value});newToken.value=token.token;await loadTokens()}catch(e){notify(String(e))}}
async function revokeToken(id:string){try{await request('/auth/tokens/'+id+'/revoke',{});newToken.value='';await loadTokens();notify('访问令牌已撤销')}catch(e){notify(String(e))}}
async function changePassword(){accountError.value='';if(passwords.value.new_password!==confirmPassword.value){accountError.value='两次新密码不一致';return}accountBusy.value=true;try{await request('/auth/password',passwords.value);passwords.value={current_password:'',new_password:''};confirmPassword.value='';notify('密码已修改，其他登录会话已失效')}catch(e){accountError.value=String(e)}finally{accountBusy.value=false}}

const form = ref({ ...state.settings })
watch(()=>state.settings.configured,()=>{form.value={...state.settings}})
async function save(){saving.value=true;try{await saveSettings(form.value)}catch{}finally{saving.value=false}}
function selectTab(value:string){void router.replace({query:{...route.query,tab:value}})}
async function copyText(value:string){try{await navigator.clipboard.writeText(value);notify('已复制')}catch{notify('请手动复制配置')}}
const snippet=computed(()=>{
const url=window.location.origin,token='YOUR_AIQA_TOKEN',project=state.projectId
if(connection.value==='cli')return `# Linux / WSL，先在 Python 环境安装 AIQA\nexport AIQA_URL=${url}\nexport AIQA_ACCESS_TOKEN=${token}\nexport AIQA_PROJECT_ID=${project}\naiqa case list\naiqa status`
if(client.value==='codex')return connection.value==='http'?`[mcp_servers.aiqa]\nurl = "${url}/mcp/"\nhttp_headers = { "Authorization" = "Bearer ${token}", "X-AIQA-Project" = "${project}" }\ntool_timeout_sec = 120`:`[mcp_servers.aiqa]\ncommand = "aiqa"\nargs = ["mcp", "serve", "--transport", "stdio"]\nenv = { "AIQA_URL" = "${url}", "AIQA_ACCESS_TOKEN" = "${token}", "AIQA_PROJECT_ID" = "${project}" }`
const config=connection.value==='http'?{type:'http',url:url+'/mcp/',headers:{Authorization:'Bearer '+token,'X-AIQA-Project':project}}:{type:'stdio',command:'aiqa',args:['mcp','serve','--transport','stdio'],env:{AIQA_URL:url,AIQA_ACCESS_TOKEN:token,AIQA_PROJECT_ID:project}}
return JSON.stringify({mcpServers:{aiqa:config}},null,2)
})
</script>
<template>
  <div class="page settings-page"><div class="page-heading"><div><h1>设置</h1><p>{{ui.deploymentMode==='local'?'配置模型与扩展 Agent 能力。':'配置模型、扩展 Agent 能力与管理账号。'}}</p></div></div>
    <div class="settings-tabs" role="tablist" aria-label="设置分类"><button v-for="entry in [{ id: 'model', icon: 'sparkles', label: '模型' }, { id: 'skills', icon: 'book', label: 'Skill' }, {id:'mcp',icon:'chain',label:'工具接入'}, { id: 'external', icon: 'chain', label: '对外接入' }, ...(ui.deploymentMode==='server'?[{id:'account',icon:'shield',label:'账号'}]:[])]" :key="entry.id" :id="`settings-${entry.id}`" role="tab" :aria-selected="tab === entry.id" :aria-controls="`settings-panel-${entry.id}`" :class="{ active: tab === entry.id }" @click="selectTab(entry.id)"><AppIcon :name="entry.icon" :size="17" />{{ entry.label }}</button></div>
    <ModelManager v-if="tab==='model'"/>
    <div v-else-if="tab==='skills'||tab==='mcp'" :id="'settings-panel-'+tab" role="tabpanel" :aria-labelledby="'settings-'+tab"><ExtensionsManager :mode="tab==='skills'?'skills':'mcp'"/></div>
    <div v-else-if="tab==='external'" id="settings-panel-external" role="tabpanel" aria-labelledby="settings-external" class="panel settings-card"><div class="settings-section-title"><div><h2>让外部 Agent 使用 AIQA</h2><p>外部 Agent 负责决策，AIQA 提供用例保存、执行和报告工具。</p></div></div><div class="integration-guide"><section><span class="guide-number">1</span><div><h3>选择接入方式</h3><div class="integration-options"><label class="field-label">方式<select v-model="connection" class="select"><option value="http">HTTP MCP（本机推荐）</option><option value="stdio">stdio MCP</option><option value="cli">CLI · Linux / WSL</option></select></label><label v-if="connection!=='cli'" class="field-label">客户端<select v-model="client" class="select"><option value="codex">Codex · TOML</option><option value="claude">Claude Code · JSON</option></select></label></div><p v-if="connection==='stdio'" class="form-hint">客户端需要能启动已安装的 aiqa 命令；Windows 也可按 README 使用 WSL Docker 桥。</p></div></section><section><span class="guide-number">2</span><div><h3>准备访问令牌和项目</h3><p class="form-hint">在下方创建令牌，将配置中的 YOUR_AIQA_TOKEN 替换为自己的值。</p><div class="project-id-line"><span>当前项目</span><strong>{{state.projectName}}</strong><code>{{state.projectId}}</code><button class="text-button" @click="copyText(state.projectId)">复制 ID</button></div></div></section><section><span class="guide-number">3</span><div><div class="section-heading"><h3>复制配置</h3><button class="button secondary" @click="copyText(snippet)"><AppIcon name="copy" :size="16"/>复制配置</button></div><pre class="integration-snippet">{{snippet}}</pre><p v-if="connection!=='cli'" class="form-hint">{{client==='codex'?'将配置合并到 ~/.codex/config.toml。':'将配置合并到项目 .mcp.json。'}}</p><p class="form-hint">配置到自己的客户端后连接 AIQA。可让 Agent 读取项目资料、保存可视化用例、执行测试并查看报告。</p></div></section></div><div class="settings-divider"/><h3>API 访问令牌</h3><p class="form-hint">外部 Agent 使用 Bearer 令牌，并通过 X-AIQA-Project 指定项目。CLI/stdio 配置 AIQA_ACCESS_TOKEN 和 AIQA_PROJECT_ID。</p><div class="add-step-row"><input v-model="tokenName" aria-label="访问令牌名称" maxlength="80"/><button class="button secondary" @click="createToken">创建访问令牌</button></div><div v-if="newToken" class="credential-placeholder"><div><strong>仅本次显示，请保存到自己的工具配置</strong><pre>{{newToken}}</pre><button class="text-button" @click="newToken=''">已保存，关闭显示</button></div></div><div v-for="token in tokens" :key="token.id" class="environment-row"><div><strong>{{token.name}}</strong><small>{{token.createdAt}}</small></div><button class="text-button danger" @click="revokeToken(token.id)">撤销</button></div></div><div v-else><section v-if="ui.user?.role==='admin'" class="panel settings-card"><h2>服务器账号</h2><p class="form-hint">管理员创建账号；新账号默认成员，不能安装运行组件。将初始密码交给本人，首次登录后修改。</p><form class="add-step-row" @submit.prevent="addAccount"><input v-model="newAccount.username" required minlength="3" maxlength="80" placeholder="账号名称" aria-label="新账号名称"/><input v-model="newAccount.password" required type="password" minlength="8" maxlength="128" autocomplete="new-password" placeholder="初始密码" aria-label="新账号初始密码"/><button class="button primary" :disabled="accountBusy">创建账号</button></form><div v-for="account in accounts" :key="account.id" class="environment-row"><strong>{{account.username}}</strong><span class="plain-tag">{{account.role==='admin'?'管理员':'成员'}}</span></div></section><form id="settings-panel-account" role="tabpanel" aria-labelledby="settings-account" class="panel settings-card account-settings" @submit.prevent="changePassword"><h2>修改登录密码</h2><div class="settings-form"><label class="field-label">当前密码<input v-model="passwords.current_password" :type="showPassword?'text':'password'" autocomplete="current-password" required minlength="8"/></label><label class="field-label">新密码<input v-model="passwords.new_password" :type="showPassword?'text':'password'" autocomplete="new-password" required minlength="8" maxlength="128"/></label><label class="field-label">确认新密码<input v-model="confirmPassword" :type="showPassword?'text':'password'" autocomplete="new-password" required minlength="8" maxlength="128"/></label><label class="step-enable"><input v-model="showPassword" type="checkbox"/>显示密码</label><p v-if="accountError" class="inline-error" role="alert">{{accountError}}</p></div><div class="settings-save"><span class="muted">修改后其他登录会话失效</span><button class="button primary" :disabled="accountBusy" type="submit">{{accountBusy?'修改中…':'修改密码'}}</button></div></form></div>
  </div>
</template>
